## training/inversion.py
"""Gradient-based parameter inversion using trained SC-FNO surrogate models.

Implements the Inverter class that reproduces the parameter inversion
experiments from Section 3.1 of the SC-FNO paper. Given synthetic
"observations" u_obs generated by the numerical solver with known true
parameters, the Inverter uses backpropagation through a frozen surrogate
model to recover those parameters by minimizing the discrepancy between
û(p_est) and u_obs.

The core insight from the paper is that SC-FNO's accurate Jacobians ∂û/∂p
provide reliable gradient signal to the Adam optimizer during inversion,
whereas FNO's poor Jacobians (R²~0.74 for PDE1, Table 1) cause the
inversion to stall or diverge.

Two inversion modes are supported:
  - Single-parameter inversion (Figure 1a): Only one parameter (e.g., α)
    is unknown; all others are treated as known. SC-FNO achieves R²=0.998
    vs FNO's R²=0.905.
  - Multi-parameter inversion (Figures 1b, 2): All parameters are unknown
    simultaneously. SC-FNO maintains R²>0.94 while FNO drops below 0.64.

The performance gap is explained by the perturbation robustness results
(Table 1 right half): during inversion, the optimizer naturally explores
parameter values outside the training range, and FNO's poor robustness to
perturbation causes the surrogate to become unreliable exactly when the
optimizer needs it most.

Configuration (config.yaml):
  - inversion.lr: 0.01       (Adam learning rate for inversion)
  - inversion.n_steps: 2000  (number of gradient descent steps)
  - inversion.optimizer: 'adam'

References:
    - SC-FNO paper Section 3.1: "Parameter Inversion from Solution Paths"
    - SC-FNO paper Figure 1: Single and multi-parameter inversion scatter plots
    - SC-FNO paper Figure 2: Multi-parameter inversion for PDE1 and PDE2
    - config.yaml: inversion.lr, inversion.n_steps, inversion.optimizer
"""

import math
from typing import Any, Dict, List, Optional, Tuple

import torch
import torch.nn as nn

from losses.data_loss import DataLoss


class Inverter:
    """Gradient-based parameter inversion using a frozen surrogate model.

    Uses backpropagation through a trained FNO or SC-FNO surrogate to recover
    physical parameters from observed solution paths. The surrogate model is
    frozen (all weights have requires_grad=False) during inversion — only the
    parameter estimate p_est receives gradient updates.

    The inversion objective is the relative L² loss between the surrogate's
    predicted solution û(p_est) and the observed solution u_obs:

        min_{p_est} ||û(p_est) - u_obs||_F / ||u_obs||_F

    This is minimized via Adam gradient descent for n_inv_steps steps.

    Attributes:
        model: The frozen surrogate model (FNO or SC-FNO). Set to eval mode
               with all parameters frozen at construction.
        cfg: The full master configuration dictionary from ConfigLoader.
        device: torch.device for tensor operations during inversion.
        lr_inv: Learning rate for the inversion Adam optimizer.
                Sourced from config.yaml key 'inversion.lr' (default 0.01).
        n_inv_steps: Number of gradient descent steps per inversion.
                     Sourced from config.yaml key 'inversion.n_steps' (default 2000).
        optimizer_type: Optimizer type string. Sourced from config.yaml key
                        'inversion.optimizer' (default 'adam').
        param_ranges: List of [low, high] bounds for each parameter, in the
                      same column order as the parameter tensor. Used to
                      initialize random starting points and optionally clamp
                      p_est during optimization.
        n_params: Number of physical parameters for the active equation.
        data_loss: DataLoss instance for computing the inversion objective.

    Example:
        >>> from models.sc_fno import build_model
        >>> from utils.config_loader import ConfigLoader
        >>>
        >>> cfg_loader = ConfigLoader('config.yaml')
        >>> cfg = cfg_loader.cfg
        >>> # Load trained model from checkpoint
        >>> checkpoint = torch.load('outputs/checkpoints/best_model.pt')
        >>> eq_cfg = {**cfg['pde1'], 'variant': 'sc_fno', 'equation': 'pde1',
        ...           'model': {**cfg['model'], **cfg['pde1'].get('model', {})}}
        >>> model = build_model(eq_cfg)
        >>> model.load_state_dict(checkpoint['model_state_dict'])
        >>> inverter = Inverter(model, cfg)
        >>> # Single-parameter inversion (α is param index 1 for PDE1)
        >>> p_est = inverter.invert_single_param(
        ...     u_obs=u_obs,       # [T_out, Sx]
        ...     u0=u0,             # [M, Sx]
        ...     coords=coords,     # [T_out, Sx, 2]
        ...     param_idx=1,       # α is index 1 in [c, α, β, γ, ω]
        ...     true_params=true_params,  # [5]
        ... )
        >>> # Multi-parameter inversion
        >>> p_est_all = inverter.invert_all_params(
        ...     u_obs=u_obs, u0=u0, coords=coords, true_params=true_params
        ... )
    """

    def __init__(self, model: nn.Module, cfg: dict) -> None:
        """Initializes the Inverter by freezing the surrogate model.

        Freezes all model parameters (requires_grad=False) and sets the model
        to eval mode. Extracts inversion hyperparameters and parameter ranges
        from the configuration.

        Args:
            model: A trained FNO or SC-FNO model instance. Must have a
                   .variant attribute (set by build_model in sc_fno.py) and
                   a .equation attribute. Will be frozen in-place — the
                   original model object is modified.
            cfg: The full master configuration dictionary loaded from
                 config.yaml. Must contain top-level keys:
                   - 'inversion': dict with 'lr', 'n_steps', 'optimizer'
                   - 'device': str
                   - 'equation': str (active equation identifier)
                 Also reads the equation-specific sub-config for parameter
                 ranges (e.g., cfg['pde1']['params']).
        """
        self.model: nn.Module = model
        self.cfg: dict = cfg

        # ------------------------------------------------------------------
        # Step 1: Set model to eval mode and freeze all parameters.
        # This is critical — during inversion, only p_est should receive
        # gradients, not the model weights.
        # ------------------------------------------------------------------
        self.model.eval()
        for param in self.model.parameters():
            param.requires_grad_(False)

        # ------------------------------------------------------------------
        # Step 2: Device setup.
        # ------------------------------------------------------------------
        device_str: str = str(
            cfg.get("device", "cuda" if torch.cuda.is_available() else "cpu")
        )
        self.device: torch.device = torch.device(device_str)

        # Move model to device if not already there.
        self.model = self.model.to(self.device)

        # ------------------------------------------------------------------
        # Step 3: Extract inversion hyperparameters from config.yaml.
        # ------------------------------------------------------------------
        inversion_cfg: dict = cfg.get("inversion", {})

        self.lr_inv: float = float(inversion_cfg.get("lr", 0.01))
        self.n_inv_steps: int = int(inversion_cfg.get("n_steps", 2000))
        self.optimizer_type: str = str(
            inversion_cfg.get("optimizer", "adam")
        ).lower()

        # ------------------------------------------------------------------
        # Step 4: Extract parameter ranges for the active equation.
        # The equation key comes from cfg['equation'] (set by main.py when
        # building the merged equation sub-config).
        # ------------------------------------------------------------------
        equation: str = str(cfg.get("equation", "pde1")).lower()
        self.param_ranges: List[List[float]] = self._extract_param_ranges(
            cfg=cfg,
            equation=equation,
        )
        self.n_params: int = len(self.param_ranges)

        # ------------------------------------------------------------------
        # Step 5: Instantiate DataLoss for the inversion objective.
        # Reuses the same relative L² formula as training for consistency.
        # ------------------------------------------------------------------
        self.data_loss: DataLoss = DataLoss()

        # ------------------------------------------------------------------
        # Print initialization summary.
        # ------------------------------------------------------------------
        print(
            f"[Inverter] Initialized for equation='{equation}' | "
            f"device={self.device} | "
            f"lr_inv={self.lr_inv} | "
            f"n_inv_steps={self.n_inv_steps} | "
            f"n_params={self.n_params} | "
            f"optimizer='{self.optimizer_type}'"
        )

    # ------------------------------------------------------------------
    # Public interface
    # ------------------------------------------------------------------

    def invert_single_param(
        self,
        u_obs: torch.Tensor,
        u0: torch.Tensor,
        coords: torch.Tensor,
        param_idx: int,
        true_params: torch.Tensor,
    ) -> torch.Tensor:
        """Inverts a single parameter while treating all others as known.

        Reproduces the single-parameter inversion experiment from Section 3.1
        (Figure 1a). Only the parameter at `param_idx` is unknown; all others
        are initialized to their true values and held fixed throughout
        optimization.

        Expected results (Table D.14, Figure 1a):
          - SC-FNO: R²=0.998 (nearly perfect recovery)
          - FNO:    R²=0.905 (significant scatter)

        Args:
            u_obs: Observed solution tensor for a single sample. Shape depends
                   on equation:
                   - ODEs:    [T_out] or [T_out, 1]
                   - 1D PDEs: [T_out, Sx]
                   - PDE3:    [Sx, Sy]
                   This is the "ground truth" observation that the inversion
                   tries to match. Generated by the numerical solver with
                   known true_params.
            u0: Initial condition for this sample. Shape depends on equation:
                - ODEs:    [M] or [1]
                - 1D PDEs: [M, Sx]
                - PDE3:    [Sx, Sy]
                Passed directly to the surrogate model's forward method.
            coords: Coordinate grid tensor (shared across batch). Shape:
                - ODEs:    [T_out, 1]
                - 1D PDEs: [T_out, Sx, 2]
                - PDE3:    [Sx, Sy, 2]
                Passed directly to the surrogate model's forward method.
            param_idx: Index of the parameter to invert (0-based). For PDE1
                       with parameters [c, α, β, γ, ω], α is at index 1.
                       Must be in [0, n_params).
            true_params: Ground truth parameter vector for this sample, shape
                         [n_params]. Used to initialize all parameters except
                         the one at param_idx to their true values.

        Returns:
            Recovered parameter vector, shape [n_params]. All parameters
            except param_idx are identical to true_params (they were fixed
            throughout optimization). The parameter at param_idx is the
            recovered estimate.

        Raises:
            ValueError: If param_idx is out of range [0, n_params).
            RuntimeError: If tensor shapes are inconsistent.

        Example:
            >>> # PDE1: invert α (index 1) while c, β, γ, ω are known
            >>> p_est = inverter.invert_single_param(
            ...     u_obs=u_obs,       # [25, 20] for PDE1 (T_out=25, Sx=20)
            ...     u0=u0,             # [5, 20] for PDE1 (M=5, Sx=20)
            ...     coords=coords,     # [25, 20, 2] for PDE1
            ...     param_idx=1,       # α is index 1 in [c, α, β, γ, ω]
            ...     true_params=true_params,  # [5]
            ... )
            >>> p_est.shape  # [5]
        """
        # Validate param_idx.
        if param_idx < 0 or param_idx >= self.n_params:
            raise ValueError(
                f"Inverter.invert_single_param: param_idx={param_idx} is out "
                f"of range [0, {self.n_params}). "
                f"The active equation has {self.n_params} parameters."
            )

        # ------------------------------------------------------------------
        # Build p_init: start from true_params, randomize only param_idx.
        # ------------------------------------------------------------------
        p_init: torch.Tensor = true_params.clone().float()

        # Randomize the target parameter within its training range.
        lo: float = self.param_ranges[param_idx][0]
        hi: float = self.param_ranges[param_idx][1]
        random_val: float = float(
            torch.rand(1).item() * (hi - lo) + lo
        )
        p_init[param_idx] = random_val

        # ------------------------------------------------------------------
        # Build fixed_mask: 1.0 for the free parameter, 0.0 for all others.
        # During optimization, p_est.grad is multiplied by this mask to
        # zero out gradients for fixed parameters.
        # ------------------------------------------------------------------
        fixed_mask: torch.Tensor = torch.zeros(
            self.n_params, dtype=torch.float32
        )
        fixed_mask[param_idx] = 1.0

        # ------------------------------------------------------------------
        # Run the optimization loop.
        # ------------------------------------------------------------------
        p_recovered: torch.Tensor = self._optimize(
            u_obs=u_obs,
            u0=u0,
            coords=coords,
            p_init=p_init,
            fixed_mask=fixed_mask,
        )

        return p_recovered

    def invert_all_params(
        self,
        u_obs: torch.Tensor,
        u0: torch.Tensor,
        coords: torch.Tensor,
        true_params: torch.Tensor,
    ) -> torch.Tensor:
        """Inverts all parameters simultaneously from a single observation.

        Reproduces the multi-parameter inversion experiment from Section 3.1
        (Figures 1b, 2). All parameters are initialized randomly and optimized
        simultaneously. This is the harder task where FNO's poor Jacobians
        cause the most degradation.

        Expected results (Figure 2, Table D.11):
          - SC-FNO: R²>0.94 for all parameters (PDE1, 5 params)
          - FNO:    R²<0.64 for some parameters (breakdown of surrogate)

        Args:
            u_obs: Observed solution tensor for a single sample. Shape depends
                   on equation (same as invert_single_param).
            u0: Initial condition for this sample (same as invert_single_param).
            coords: Coordinate grid tensor (same as invert_single_param).
            true_params: Ground truth parameter vector, shape [n_params].
                         NOT used for initialization (all params are randomized).
                         Stored only for reference — the Evaluator uses it to
                         compute R² after inversion.

        Returns:
            Recovered parameter vector, shape [n_params]. All parameters are
            the result of the joint optimization.

        Example:
            >>> # PDE2: invert all 4 parameters [α, γ, δ, ω] simultaneously
            >>> p_est = inverter.invert_all_params(
            ...     u_obs=u_obs,       # [25, 40] for PDE2 (T_out=25, Sx=40)
            ...     u0=u0,             # [5, 40] for PDE2 (M=5, Sx=40)
            ...     coords=coords,     # [25, 40, 2] for PDE2
            ...     true_params=true_params,  # [4] — not used for init
            ... )
            >>> p_est.shape  # [4]
        """
        # ------------------------------------------------------------------
        # Build p_init: sample all parameters randomly from their ranges.
        # Do NOT use true_params — the optimizer starts from a random point.
        # ------------------------------------------------------------------
        p_init_values: List[float] = []
        for lo_hi in self.param_ranges:
            lo: float = lo_hi[0]
            hi: float = lo_hi[1]
            val: float = float(torch.rand(1).item() * (hi - lo) + lo)
            p_init_values.append(val)

        p_init: torch.Tensor = torch.tensor(
            p_init_values, dtype=torch.float32
        )

        # ------------------------------------------------------------------
        # No fixed mask — all parameters are free to be optimized.
        # ------------------------------------------------------------------
        fixed_mask: Optional[torch.Tensor] = None

        # ------------------------------------------------------------------
        # Run the optimization loop.
        # ------------------------------------------------------------------
        p_recovered: torch.Tensor = self._optimize(
            u_obs=u_obs,
            u0=u0,
            coords=coords,
            p_init=p_init,
            fixed_mask=fixed_mask,
        )

        return p_recovered

    def _optimize(
        self,
        u_obs: torch.Tensor,
        u0: torch.Tensor,
        coords: torch.Tensor,
        p_init: torch.Tensor,
        fixed_mask: Optional[torch.Tensor],
    ) -> torch.Tensor:
        """Core gradient descent loop for parameter inversion.

        Minimizes the relative L² loss between the surrogate's predicted
        solution û(p_est) and the observed solution u_obs using Adam:

            min_{p_est} ||û(p_est) - u_obs||_F / ||u_obs||_F

        The surrogate model is frozen — only p_est receives gradient updates.
        If fixed_mask is provided, gradients for fixed parameters are zeroed
        before each optimizer step.

        Args:
            u_obs: Observed solution tensor (single sample, no batch dim).
                   Shape: [T_out, Sx] for 1D PDEs, [T_out] for ODEs,
                   [Sx, Sy] for PDE3.
            u0: Initial condition (single sample, no batch dim).
                Shape: [M, Sx] for 1D PDEs, [M] for ODEs, [Sx, Sy] for PDE3.
            coords: Coordinate grid (shared, no batch dim).
                    Shape: [T_out, Sx, 2] for 1D PDEs, [T_out, 1] for ODEs,
                    [Sx, Sy, 2] for PDE3.
            p_init: Initial parameter estimate, shape [n_params]. Will be
                    cloned internally — the input is not modified.
            fixed_mask: Optional float tensor of shape [n_params]. If provided,
                        p_est.grad is multiplied by this mask before each
                        optimizer step to zero out gradients for fixed
                        parameters. None means all parameters are free.

        Returns:
            Recovered parameter vector, shape [n_params]. Detached from the
            computation graph. On CPU.

        Note:
            If the loss becomes NaN or Inf during optimization (e.g., due to
            extreme parameter values causing model instability), the loop is
            terminated early and the last valid p_est is returned.
        """
        # ------------------------------------------------------------------
        # Step 1: Setup — move tensors to device, create leaf variable p_est.
        # ------------------------------------------------------------------
        # Move observations and inputs to device, detach from any upstream graph.
        u_obs_dev: torch.Tensor = u_obs.float().to(self.device).detach()
        u0_dev: torch.Tensor = u0.float().to(self.device).detach()
        coords_dev: torch.Tensor = coords.float().to(self.device).detach()

        # Create the optimizable parameter estimate as a leaf tensor.
        # p_init is cloned to avoid modifying the caller's tensor.
        p_est: torch.Tensor = p_init.clone().float().to(self.device)
        p_est.requires_grad_(True)

        # Move fixed_mask to device if provided.
        fixed_mask_dev: Optional[torch.Tensor] = None
        if fixed_mask is not None:
            fixed_mask_dev = fixed_mask.float().to(self.device)

        # ------------------------------------------------------------------
        # Step 2: Initialize the optimizer.
        # ------------------------------------------------------------------
        if self.optimizer_type == "adam":
            optimizer: torch.optim.Optimizer = torch.optim.Adam(
                [p_est], lr=self.lr_inv
            )
        elif self.optimizer_type == "lbfgs":
            # L-BFGS is sometimes used for inversion but requires a closure.
            # Fall back to Adam for simplicity and consistency with the paper.
            optimizer = torch.optim.Adam([p_est], lr=self.lr_inv)
        elif self.optimizer_type == "sgd":
            optimizer = torch.optim.SGD([p_est], lr=self.lr_inv)
        else:
            # Default to Adam for any unrecognized optimizer type.
            optimizer = torch.optim.Adam([p_est], lr=self.lr_inv)

        # ------------------------------------------------------------------
        # Step 3: Add batch dimension for model forward pass.
        # The model expects [B, n_params], [B, ...], [B, ...] or shared coords.
        # For inversion, B=1 (single sample).
        # ------------------------------------------------------------------
        # u0 and u_obs need a batch dimension; coords is shared (no batch dim
        # in the dataset convention, but the model's _build_input handles this).
        u0_batch: torch.Tensor = u0_dev.unsqueeze(0)  # [1, M, Sx] or [1, M] etc.

        # ------------------------------------------------------------------
        # Step 4: Track the last valid p_est for early termination on NaN.
        # ------------------------------------------------------------------
        last_valid_p_est: torch.Tensor = p_est.detach().clone()

        # ------------------------------------------------------------------
        # Step 5: Optimization loop.
        # ------------------------------------------------------------------
        for step in range(self.n_inv_steps):
            optimizer.zero_grad()

            # Add batch dimension to p_est for model forward pass.
            params_batch: torch.Tensor = p_est.unsqueeze(0)  # [1, n_params]

            # Forward pass through the frozen surrogate.
            # The model is in eval mode with all weights frozen.
            u_pred: torch.Tensor = self.model(
                params_batch,
                u0_batch,
                coords_dev,
            )
            # u_pred shape: [1, T_out, Sx] for 1D PDEs, [1, T_out] for ODEs,
            #               [1, Sx, Sy] for PDE3.

            # Remove batch dimension for loss computation.
            u_pred_squeezed: torch.Tensor = u_pred.squeeze(0)
            # u_pred_squeezed shape: [T_out, Sx] or [T_out] or [Sx, Sy].

            # Compute relative L² loss between predicted and observed solution.
            # Both tensors need a batch dimension for DataLoss.forward.
            loss: torch.Tensor = self.data_loss(
                u_pred_squeezed.unsqueeze(0),  # [1, T_out, Sx]
                u_obs_dev.unsqueeze(0),        # [1, T_out, Sx]
            )

            # ------------------------------------------------------------------
            # Check for NaN/Inf loss — terminate early if detected.
            # ------------------------------------------------------------------
            if not torch.isfinite(loss):
                # Return the last valid estimate rather than a NaN tensor.
                break

            # Save current valid estimate before backward pass.
            last_valid_p_est = p_est.detach().clone()

            # Backpropagate through the surrogate to compute ∂loss/∂p_est.
            loss.backward()

            # ------------------------------------------------------------------
            # Apply fixed mask to zero out gradients for fixed parameters.
            # This ensures only the free parameters are updated.
            # ------------------------------------------------------------------
            if fixed_mask_dev is not None and p_est.grad is not None:
                p_est.grad.data.mul_(fixed_mask_dev)

            # ------------------------------------------------------------------
            # Optimizer step: update p_est.
            # ------------------------------------------------------------------
            optimizer.step()

            # ------------------------------------------------------------------
            # Optional: clamp p_est to physically meaningful bounds.
            # Allow 50% margin beyond training range to permit exploration
            # (consistent with the perturbation experiment in Section 3.2).
            # ------------------------------------------------------------------
            with torch.no_grad():
                for param_i in range(self.n_params):
                    lo: float = self.param_ranges[param_i][0]
                    hi: float = self.param_ranges[param_i][1]
                    margin: float = 0.5 * (hi - lo)
                    # Clamp to [lo - margin, hi + margin].
                    p_est.data[param_i].clamp_(
                        min=lo - margin,
                        max=hi + margin,
                    )

        # ------------------------------------------------------------------
        # Step 6: Return the recovered parameter vector.
        # Use last_valid_p_est if the final p_est is NaN/Inf.
        # ------------------------------------------------------------------
        final_p_est: torch.Tensor = p_est.detach()

        if not torch.isfinite(final_p_est).all():
            final_p_est = last_valid_p_est

        # Return on CPU for consistency with dataset tensors.
        return final_p_est.cpu()

    # ------------------------------------------------------------------
    # Private helpers
    # ------------------------------------------------------------------

    def _extract_param_ranges(
        self,
        cfg: dict,
        equation: str,
    ) -> List[List[float]]:
        """Extracts parameter ranges for the active equation from config.

        Reads the equation-specific sub-config (e.g., cfg['pde1']['params'])
        and returns an ordered list of [low, high] bounds matching the
        parameter tensor column order.

        The ordering is determined by the insertion order of keys in the
        YAML config file (Python 3.7+ guarantees dict insertion order),
        which matches the order used by the generators and dataset.

        Args:
            cfg: The full master configuration dictionary.
            equation: Equation identifier string, e.g. 'ode1', 'pde1', 'pde3'.

        Returns:
            List of [low, high] pairs, one per parameter, in column order.
            Returns an empty list if the equation sub-config is not found.

        Example:
            >>> ranges = inverter._extract_param_ranges(cfg, 'pde1')
            >>> ranges
            [[0.0, 0.25], [0.0, 0.1], [0.0, 0.25], [0.0, 0.25], [0.0, 0.25]]
            >>> # Corresponds to [c, α, β, γ, ω] for PDE1 (Table B.6)
        """
        # Map equation identifier to config key.
        # Some equations have special keys (e.g., 'pde2_zoned' for zoned PDE2).
        equation_key_map: Dict[str, str] = {
            "ode1": "ode1",
            "ode2": "ode2",
            "pde1": "pde1",
            "pde2": "pde2",
            "pde3": "pde3",
            "pde4": "pde4",
        }

        config_key: str = equation_key_map.get(equation, equation)
        eq_cfg: dict = cfg.get(config_key, {})

        # Extract parameter ranges from the equation sub-config.
        params_cfg: dict = eq_cfg.get("params", {})

        if not params_cfg:
            # Fallback: try to read from the top-level cfg directly.
            # This handles the case where cfg is already the equation sub-config.
            params_cfg = cfg.get("params", {})

        if not params_cfg:
            print(
                f"[Inverter] WARNING: No parameter ranges found for "
                f"equation='{equation}'. Using empty ranges. "
                f"Inversion initialization will use [0, 1] for all parameters."
            )
            # Return default [0, 1] ranges as a fallback.
            n_params_fallback: int = int(cfg.get("n_params", eq_cfg.get("n_params", 5)))
            return [[0.0, 1.0]] * n_params_fallback

        # Build ordered list of [low, high] pairs.
        # Dict insertion order is preserved in Python 3.7+.
        param_ranges: List[List[float]] = []
        for param_name, bounds in params_cfg.items():
            if isinstance(bounds, (list, tuple)) and len(bounds) >= 2:
                lo: float = float(bounds[0])
                hi: float = float(bounds[1])
                param_ranges.append([lo, hi])
            else:
                # Unexpected format — use [0, 1] as fallback.
                print(
                    f"[Inverter] WARNING: Unexpected format for parameter "
                    f"'{param_name}' bounds: {bounds}. Using [0, 1]."
                )
                param_ranges.append([0.0, 1.0])

        return param_ranges
